android.extraProguardRules:
# --- Keep rules for Dash release builds ---
# R8 strips aggressively; anything reached only by reflection or from
# native code must be kept explicitly or the release build crashes where
# the debug build did not.

# React Native core
-keep,allowobfuscation @interface com.facebook.proguard.annotations.DoNotStrip
-keep,allowobfuscation @interface com.facebook.proguard.annotations.KeepGettersAndSetters
-keep @com.facebook.proguard.annotations.DoNotStrip class *
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }

# Hermes
-keep class com.facebook.hermes.unicode.** { *; }
-keep class com.facebook.jni.** { *; }

# Expo modules are resolved by name at runtime
-keep class expo.modules.** { *; }
-keep class expo.core.** { *; }
-keepclassmembers class * { @expo.modules.core.interfaces.ExpoProp <methods>; }
-keepclassmembers class * { @expo.modules.core.interfaces.ExpoMethod <methods>; }

# Reanimated / worklets run through JNI
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }

# react-native-svg and react-native-screens
-keep public class com.horcrux.svg.** { *; }
-keep class com.swmansion.rnscreens.** { *; }

# Google Maps
-keep class com.google.android.gms.maps.** { *; }
-keep interface com.google.android.gms.maps.** { *; }
-keep class com.airbnb.android.react.maps.** { *; }

# OkHttp / Okio emit build warnings for optional deps
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn javax.annotation.**
-dontwarn org.conscrypt.**

# Keep line numbers so Play Console stack traces stay readable
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile
